import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { ConvexGeometry } from 'three/addons/geometries/ConvexGeometry.js';
import katex from 'katex';
import { mathNumber } from './number-format.js';

const formula=s=>`<div class="geometry-math">${katex.renderToString(s,{throwOnError:false,displayMode:true})}</div>`;
export const polarTheory={
 dual:`<div class="concept-card"><span class="eyebrow">CARAS ↔ VÉRTICES</span><h2>Poliedros conjugados o duales</h2><p>Aquí usamos «conjugados» para los poliedros duales: cada cara de uno corresponde a un vértice del otro, y cada arista conserva una arista correspondiente. No significa que tengan el mismo volumen.</p></div>
 <div class="polar-pairs"><span>Cubo ↔ Octaedro</span><span>Dodecaedro ↔ Icosaedro</span><span>Tetraedro ↔ Tetraedro</span></div>
 ${formula('C^*=V,\\qquad V^*=C,\\qquad A^*=A')}
 <p>El asterisco indica el dual. En un cubo, las seis caras corresponden a los seis vértices de un octaedro; sus ocho vértices corresponden a ocho caras. El tetraedro es <strong>autodual</strong>.</p>
 <section class="polar-lab" aria-label="Laboratorio de poliedros conjugados"><h3>Construye la correspondencia</h3><div class="polar-controls"><label>Poliedro<select id="dualExample"><option value="current">Sólido del laboratorio</option><option value="cube">Cubo</option><option value="octa">Octaedro</option><option value="dode">Dodecaedro</option><option value="ico">Icosaedro</option><option value="tetra">Tetraedro</option></select></label><label><input id="polarOriginal" type="checkbox" checked> Original · violeta</label><label><input id="polarDual" type="checkbox" checked> Conjugado · naranja</label><button id="polarCenter" class="ghost-btn">Centrar</button></div><div id="polarViewport" class="polar-viewport"><canvas id="polarCanvas" aria-label="Poliedro original y su dual, arrastra para girar"></canvas></div><p>Arrastra para girar; rueda o pellizca para acercar. La cara resaltada corresponde al punto naranja. Ambos pueden ocultarse por separado.</p><button id="polarNextFace" class="ghost-btn">Señalar otra cara y su vértice dual</button><div id="dualCounts" class="polar-explanation" aria-live="polite"></div></section>
 <h3>¿Cómo se obtiene el polar?</h3><p>Tomamos una esfera de centro O y radio 1, con O dentro del poliedro. Una cara con ecuación n·x = d, donde n es su normal exterior unitaria, produce el vértice polar n/d. Aquí el dual se reduce uniformemente para mostrarlo inscrito; cambiar esa escala no cambia qué cara corresponde a cada vértice.</p>
 ${formula('\\mathbf x^*=\\frac{\\mathbf n}{d}\\quad(\\|\\mathbf n\\|=1)')}
 <p>Para los platónicos también se puede unir los centros de caras vecinas. En general, unir centros sin más no sustituye la construcción polar. Los duales de los arquimedianos se conocen como sólidos de Catalan; el dual de un prisma es una bipirámide.</p><p class="polar-note">La dualidad del poliedro completo y el triedro polar de un vértice son conceptos relacionados, pero no son la misma construcción.</p><a href="#teoria/polares">Ver diedro y triedro polar →</a><p class="source-note">Referencia: <a href="https://mathworld.wolfram.com/DualPolyhedron.html" target="_blank" rel="noreferrer">Wolfram MathWorld · Dual Polyhedron</a>.</p>`,
 polar:`<div class="concept-card"><span class="eyebrow">PERPENDICULARIDAD Y SUPLEMENTOS</span><h2>Diedro y triedro polar</h2><p>Un diedro une dos caras; un triedro reúne tres caras en un vértice. En el triedro, «ángulo de cara» significa el ángulo plano entre dos aristas, no el área de una cara.</p></div>
 <h3>1. Del diedro a sus normales exteriores</h3><p>Cortamos perpendicularmente a la arista común. Las dos normales exteriores son perpendiculares a las caras: el ángulo β entre ellas es el suplemento del diedro interior δ. Lo llamaremos <strong>ángulo entre normales</strong>, para no confundirlo con otro poliedro.</p>
 ${formula('\\delta+\\beta=180^\\circ,\\qquad\\beta=180^\\circ-\\delta')}
 <section class="polar-lab"><label for="polarDihedral">Diedro interior δ · <output id="polarDihedralValue">90°</output></label><input id="polarDihedral" type="range" min="20" max="160" step="1" value="90"><div id="dihedralDiagram"></div><div id="dihedralCalculation" aria-live="polite"></div><p>Violeta: las caras en el corte. Naranja: sus normales exteriores n₁ y n₂. Los sectores sombreados muestran los dos ángulos; no son longitudes.</p></section>
 <h3>2. Construcción del triedro polar o suplementario</h3><ol><li>Desde el vértice O, traza una perpendicular a cada cara.</li><li>Escoge en cada perpendicular la semirrecta que apunta hacia fuera del triedro.</li><li>Las tres semirrectas forman las aristas del triedro polar.</li></ol>
 <p>Si αᵢ es un ángulo de cara y δᵢ el diedro opuesto a esa cara, se cumple:</p>
 ${formula('\\alpha_i^*=180^\\circ-\\delta_i')}${formula('\\delta_i^*=180^\\circ-\\alpha_i')}
 <p>El subíndice i identifica la pareja opuesta correspondiente. El polar del polar recupera el triedro original. Estos son suplementos (180°), no complementos (90°).</p>
 <section class="polar-lab"><h3>Explora los dos triedros en 3D</h3><div class="polar-controls"><label>Ejemplo<select id="trihedralExample"><option value="current">Vértice del sólido actual</option><option value="cube">Esquina del cubo</option><option value="tetra">Vértice del tetraedro</option><option value="dode">Vértice del dodecaedro</option></select></label><label><input id="polarOriginal" type="checkbox" checked> Triedro · violeta</label><label><input id="polarDual" type="checkbox" checked> Polar · naranja</label><button id="polarCenter" class="ghost-btn">Centrar</button></div><p id="trihedralWarning" class="polar-note" hidden></p><div id="polarViewport" class="polar-viewport"><canvas id="polarCanvas" aria-label="Triedro y triedro polar interactivos"></canvas></div><p>Los dos comparten el vértice O. Las tres flechas naranjas son normales exteriores a las caras violetas. Arrastra para girar. Las superficies curvas son secciones sobre una esfera auxiliar, no caras planas del poliedro.</p><label for="polarPair">Pareja que se destaca</label><select id="polarPair"><option value="0">Pareja 1</option><option value="1">Pareja 2</option><option value="2">Pareja 3</option></select><div id="trihedralComparison" aria-live="polite"></div></section>
 <h3>Ejemplos y propiedades</h3><p>En la esquina de un cubo, los ángulos de cara y los diedros son de 90°: el polar también es trirrectángulo. En un tetraedro regular, α = 60° y δ ≈ 70,53°; el polar tiene α* ≈ 109,47° y δ* = 120°. Los ángulos no dependen de cuánto mida la arista.</p>
 ${formula('0<\\alpha_1+\\alpha_2+\\alpha_3<360^\\circ')}${formula('180^\\circ<\\delta_1+\\delta_2+\\delta_3<540^\\circ')}
 <p>Estas desigualdades son para triedros convexos no degenerados. Su ángulo sólido se mide en estereorradianes: Ω = δ₁ + δ₂ + δ₃ − π cuando los diedros están en radianes. No se debe sumar directamente un valor en grados con uno en radianes.</p><a href="#teoria/conjugados">Comparar con los poliedros conjugados →</a><p class="source-note">Fuentes: <a href="https://matematicas.unex.es/~trinidad/MM/tema1.pdf" target="_blank" rel="noreferrer">Universidad de Extremadura · Trigonometría esférica</a> y <a href="https://rodin.uca.es/bitstream/handle/10498/9873/teap.pdf?isAllowed=y&amp;sequence=1" target="_blank" rel="noreferrer">Universidad de Cádiz · Triedros y triángulos polares</a>.</p>`
};

export function trihedralData(rays){
 const u=rays.map(r=>r.clone().normalize());
 const normals=u.map((ray,i)=>{const n=new THREE.Vector3().crossVectors(u[(i+1)%3],u[(i+2)%3]).normalize();if(n.dot(ray)>0)n.negate();return n});
 const angle=(a,b)=>Math.acos(THREE.MathUtils.clamp(a.dot(b),-1,1));
 return{rays:u,normals,rows:u.map((_,i)=>{const j=(i+1)%3,k=(i+2)%3,alpha=THREE.MathUtils.radToDeg(angle(u[j],u[k])),polarAlpha=THREE.MathUtils.radToDeg(angle(normals[j],normals[k]));return{alpha,delta:180-polarAlpha,polarAlpha,polarDelta:180-alpha}})};
}

export function mountPolarLesson(kind,{currentAnalysis,currentName,getExample,format}){
 const $=id=>document.getElementById(id),host=$('polarViewport'),canvas=$('polarCanvas');
 const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(38,1,.01,100),renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));
 const controls=new OrbitControls(camera,canvas);controls.enableDamping=true;controls.minDistance=2;controls.maxDistance=18;
 scene.add(new THREE.HemisphereLight(0xffffff,0x718096,3));const light=new THREE.DirectionalLight(0xffffff,3);light.position.set(4,6,7);scene.add(light);
 let group=new THREE.Group(),original,polar,frame,disposed=false,faceIndex=0,activeAnalysis,dualPoints,tri,fitDistance=8,zoomRatio=1;scene.add(group);
 const zoomBar=document.createElement('div');zoomBar.className='polar-zoom';zoomBar.setAttribute('aria-label','Tamaño de la figura');zoomBar.innerHTML='<button id="polarZoomOut" class="ghost-btn" type="button" aria-label="Reducir figura">− Reducir</button><button id="polarZoomIn" class="ghost-btn" type="button" aria-label="Ampliar figura">+ Ampliar</button><output id="polarZoomValue" aria-live="polite">100 %</output>'+(kind==='dual'?'<button id="polarFocusDual" class="ghost-btn" type="button">Enfocar conjugado</button>':'');host.before(zoomBar);
 const disposeObject=o=>o.traverse(x=>{x.geometry?.dispose();if(x.material)(Array.isArray(x.material)?x.material:[x.material]).forEach(m=>{m.map?.dispose();m.dispose()})});
 function clear(){disposeObject(group);scene.remove(group);group=new THREE.Group();scene.add(group)}
 function frameModel(resetOrientation=false){
  const w=host.clientWidth,h=host.clientHeight;if(!w||!h)return;camera.aspect=w/h;camera.updateProjectionMatrix();
  let radius=2.85,center=new THREE.Vector3();if(kind==='dual'&&original&&polar){group.updateMatrixWorld(true);const bounds=new THREE.Box3();if(original.visible)bounds.expandByObject(original);if(polar.visible)bounds.expandByObject(polar);if(!bounds.isEmpty()){const sphere=bounds.getBoundingSphere(new THREE.Sphere());radius=sphere.radius;center=sphere.center}else radius=2.3}
  const vertical=THREE.MathUtils.degToRad(camera.fov),horizontal=2*Math.atan(Math.tan(vertical/2)*camera.aspect);fitDistance=radius/Math.sin(Math.min(vertical,horizontal)/2)*1.06;
  const direction=resetOrientation?new THREE.Vector3(5,3.7,6).normalize():camera.position.clone().sub(controls.target).normalize();controls.target.copy(center);controls.minDistance=Math.max(.15,radius*.6);controls.maxDistance=Math.max(18,fitDistance*8);camera.position.copy(center).addScaledVector(direction,fitDistance/zoomRatio);controls.update();updateZoom();
 }
 function updateZoom(){zoomRatio=fitDistance/Math.max(.01,camera.position.distanceTo(controls.target));$('polarZoomValue').textContent=`${Math.round(zoomRatio*100)} %`}
 function reset(){zoomRatio=1;frameModel(true)}
 function resize(){const w=host.clientWidth,h=host.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);frameModel()}
 function zoom(factor){const offset=camera.position.clone().sub(controls.target),distance=THREE.MathUtils.clamp(offset.length()*factor,controls.minDistance,controls.maxDistance);camera.position.copy(controls.target).add(offset.setLength(distance));controls.update();updateZoom()}
 controls.addEventListener('change',updateZoom);$('polarZoomIn').addEventListener('click',()=>zoom(.8));$('polarZoomOut').addEventListener('click',()=>zoom(1.25));
 const observer=new ResizeObserver(resize);observer.observe(host);
 function animate(){if(disposed)return;frame=requestAnimationFrame(animate);controls.update();renderer.render(scene,camera)}
 function line(parent,points,color){const geo=new THREE.BufferGeometry().setFromPoints(points);parent.add(new THREE.Line(geo,new THREE.LineBasicMaterial({color,depthTest:false})))}
 function dot(parent,p,color,r=.075){const mesh=new THREE.Mesh(new THREE.SphereGeometry(r,14,10),new THREE.MeshBasicMaterial({color,depthTest:false}));mesh.position.copy(p);mesh.renderOrder=50;parent.add(mesh)}
 function label(parent,text,p,color){const image=document.createElement('canvas');image.width=192;image.height=96;const c=image.getContext('2d');c.fillStyle='rgba(255,255,255,.94)';c.fillRect(0,0,192,96);c.font='bold 48px Arial';c.textAlign='center';c.textBaseline='middle';c.fillStyle=color;c.fillText(text,96,48);const map=new THREE.CanvasTexture(image),sprite=new THREE.Sprite(new THREE.SpriteMaterial({map,depthTest:false}));sprite.position.copy(p);sprite.scale.set(.6,.3,1);parent.add(sprite)}
 function surface(geometry,color,opacity){const root=new THREE.Group();root.add(new THREE.Mesh(geometry,new THREE.MeshPhongMaterial({color,transparent:true,opacity,side:THREE.DoubleSide,depthWrite:false})),new THREE.LineSegments(new THREE.EdgesGeometry(geometry,1),new THREE.LineBasicMaterial({color})));group.add(root);return root}
 function visibility(){original.visible=$('polarOriginal').checked;polar.visible=$('polarDual').checked}
 function analysisFor(key){if(key==='current')return{analysis:currentAnalysis,name:currentName};return getExample(key)}
 function highlightFace(){
  const old=group.getObjectByName('correspondence');if(old){disposeObject(old);group.remove(old)}const root=new THREE.Group();root.name='correspondence';group.add(root);
  const face=activeAnalysis.faces[faceIndex%activeAnalysis.faces.length],vertices=face.vertices,geo=new THREE.BufferGeometry(),positions=[];for(let i=1;i<vertices.length-1;i++)positions.push(...vertices[0].toArray(),...vertices[i].toArray(),...vertices[i+1].toArray());geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));geo.computeVertexNormals();
  const patch=new THREE.Mesh(geo,new THREE.MeshBasicMaterial({color:0x55bdb3,side:THREE.DoubleSide,transparent:true,opacity:.75,depthTest:false}));patch.visible=original.visible;root.add(patch);const dualRadius=Math.max(...dualPoints.map(p=>p.length()));dot(root,dualPoints[faceIndex%dualPoints.length],0xf57819,dualRadius*.035);root.children.at(-1).visible=polar.visible;
  const name=$('dualExample').selectedOptions[0].value==='current'?currentName:$('dualExample').selectedOptions[0].textContent;
  $('dualCounts').innerHTML=`<p><strong>${name}</strong>: ${activeAnalysis.faces.length} caras, ${activeAnalysis.vertices.size} vértices, ${activeAnalysis.edges.size} aristas.</p><p><strong>Conjugado</strong>: ${activeAnalysis.vertices.size} caras, ${activeAnalysis.faces.length} vértices, ${activeAnalysis.edges.size} aristas.</p><p>Cara ${faceIndex%activeAnalysis.faces.length+1} ↔ vértice dual ${faceIndex%activeAnalysis.faces.length+1}. Sus bordes corresponden a las aristas que llegan al punto dual.</p>`;
 }
 function drawDual(){clear();const data=analysisFor($('dualExample').value);activeAnalysis=data.analysis;const g=new ConvexGeometry([...activeAnalysis.vertices.values()].map(p=>p.clone()));original=surface(g,0x675ae8,.2);dualPoints=activeAnalysis.faces.map(f=>f.normal.clone().divideScalar(f.normal.dot(f.center)));let bound=0;activeAnalysis.faces.forEach(f=>dualPoints.forEach(p=>bound=Math.max(bound,f.normal.dot(p)/f.normal.dot(f.center))));dualPoints.forEach(p=>p.multiplyScalar(1/bound));polar=surface(new ConvexGeometry(dualPoints),0xef8a32,.4);g.computeBoundingSphere();group.scale.setScalar(2/g.boundingSphere.radius);visibility();highlightFace();reset()}
 function arc(parent,a,b,color){const theta=a.angleTo(b);const points=Array.from({length:33},(_,i)=>a.clone().multiplyScalar(Math.sin((1-i/32)*theta)).addScaledVector(b,Math.sin(i/32*theta)).divideScalar(Math.sin(theta)).multiplyScalar(1.7));line(parent,points,color)}
 function cone(rays,color,prefix){const root=new THREE.Group();group.add(root);rays.forEach((r,i)=>{root.add(new THREE.ArrowHelper(r,new THREE.Vector3(),2.2,color,.18,.08));dot(root,r.clone().multiplyScalar(1.7),color,.05);label(root,`${prefix}${i+1}`,r.clone().multiplyScalar(2.45),prefix==='u'?'#5141cc':'#ad4e10')});const positions=[];for(let i=0;i<3;i++){positions.push(0,0,0,...rays[i].clone().multiplyScalar(1.7).toArray(),...rays[(i+1)%3].clone().multiplyScalar(1.7).toArray());arc(root,rays[i],rays[(i+1)%3],color)}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));geo.computeVertexNormals();root.add(new THREE.Mesh(geo,new THREE.MeshBasicMaterial({color,transparent:true,opacity:.16,side:THREE.DoubleSide,depthWrite:false})));
  const cap=[],steps=14,point=(i,j)=>rays[0].clone().multiplyScalar(1-(i+j)/steps).addScaledVector(rays[1],i/steps).addScaledVector(rays[2],j/steps).normalize().multiplyScalar(1.7);for(let i=0;i<steps;i++)for(let j=0;j<steps-i;j++){cap.push(...point(i,j).toArray(),...point(i+1,j).toArray(),...point(i,j+1).toArray());if(i+j<steps-1)cap.push(...point(i+1,j).toArray(),...point(i+1,j+1).toArray(),...point(i,j+1).toArray())}const shell=new THREE.BufferGeometry();shell.setAttribute('position',new THREE.Float32BufferAttribute(cap,3));root.add(new THREE.Mesh(shell,new THREE.MeshBasicMaterial({color,transparent:true,opacity:.23,side:THREE.DoubleSide,depthWrite:false})));return root}
 function highlightPair(){
  const old=group.getObjectByName('pair');if(old){disposeObject(old);group.remove(old)}const root=new THREE.Group();root.name='pair';group.add(root);const i=Number($('polarPair').value),j=(i+1)%3,k=(i+2)%3;
  // Spherical sector bounded by the two outward normals: alpha* = 180 - delta.
  const a=tri.normals[j],b=tri.normals[k],theta=a.angleTo(b),positions=[];for(let s=0;s<32;s++){const at=t=>a.clone().multiplyScalar(Math.sin((1-t)*theta)).addScaledVector(b,Math.sin(t*theta)).divideScalar(Math.sin(theta)).multiplyScalar(1.7);positions.push(0,0,0,...at(s/32).toArray(),...at((s+1)/32).toArray())}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));root.add(new THREE.Mesh(geo,new THREE.MeshBasicMaterial({color:0xffbe48,side:THREE.DoubleSide,transparent:true,opacity:.65,depthTest:false})));root.visible=polar.visible;
  $('trihedralComparison').innerHTML=`<div class="polar-angle-cards">${tri.rows.map((r,index)=>`<section class="${index===i?'selected':''}"><h4>Pareja ${index+1}</h4><p>Cara original α = ${format(r.alpha)}°</p><p>Diedro original δ = ${format(r.delta)}°</p><p>Cara polar α* = ${format(r.polarAlpha)}°</p><p>Diedro polar δ* = ${format(r.polarDelta)}°</p></section>`).join('')}</div>${formula(`\\alpha_{${i+1}}^*=180^\\circ-${mathNumber(tri.rows[i].delta)}^\\circ\\approx ${mathNumber(tri.rows[i].polarAlpha)}^\\circ`)}${formula(`\\delta_{${i+1}}^*=180^\\circ-${mathNumber(tri.rows[i].alpha)}^\\circ\\approx ${mathNumber(tri.rows[i].polarDelta)}^\\circ`)}<p>El sector naranja destaca la cara del polar de la pareja ${i+1}; su diedro original correspondiente está en la arista violeta opuesta. Las cifras mostradas están redondeadas.</p>`;
  line(root,[new THREE.Vector3(),tri.rays[i].clone().multiplyScalar(2.25)],0x35a89d);
  root.children.at(-1).visible=original.visible;
 }
 function drawTriedro(){clear();let data=analysisFor($('trihedralExample').value),item=data.analysis.vertexAngles.find(v=>v.faces.length===3&&v.rays.length===3);$('trihedralWarning').hidden=!!item;if(!item){$('trihedralWarning').textContent=`En ${data.name}, este vértice reúne ${data.analysis.vertexAngles[0].faces.length} caras, no tres. Mostramos la esquina de un cubo como ejemplo de triedro; no tomamos tres caras sueltas del sólido.`;data=getExample('cube');item=data.analysis.vertexAngles.find(v=>v.rays.length===3)}tri=trihedralData(item.rays);original=cone(tri.rays,0x675ae8,'u');polar=cone(tri.normals,0xef8a32,'n');dot(group,new THREE.Vector3(),0x35a89d);label(group,'O',new THREE.Vector3(0,-.25,0),'#176b63');visibility();highlightPair();reset()}
 if(kind==='dual'){$('dualExample').addEventListener('change',()=>{faceIndex=0;drawDual()});$('polarNextFace').addEventListener('click',()=>{faceIndex++;highlightFace()});drawDual()}
 else{$('trihedralExample').addEventListener('change',drawTriedro);$('polarPair').addEventListener('change',highlightPair);drawTriedro();mountDiedro($,format)}
 for(const id of ['polarOriginal','polarDual'])$(id).addEventListener('change',()=>{visibility();if(kind==='dual')highlightFace();else highlightPair();reset()});$('polarCenter').addEventListener('click',reset);
 if(kind==='dual')$('polarFocusDual').addEventListener('click',()=>{$('polarOriginal').checked=false;$('polarDual').checked=true;visibility();highlightFace();reset()});
 resize();animate();
 return()=>{disposed=true;cancelAnimationFrame(frame);observer.disconnect();controls.dispose();disposeObject(group);renderer.dispose();renderer.forceContextLoss()};
}

function mountDiedro($,format){
 function draw(){const degrees=Number($('polarDihedral').value),theta=degrees*Math.PI/180,cx=210,cy=155,r=100,point=(angle,length=r)=>[cx+length*Math.cos(angle),cy-length*Math.sin(angle)],p=point(theta),n1=point(-Math.PI/2),n2=point(theta+Math.PI/2),nstart=theta+Math.PI/2,end=3*Math.PI/2,arcpoint=point(theta,48),ns=point(nstart,58),ne=point(end,58);
  $('polarDihedralValue').textContent=`${format(degrees)}°`;
  $('dihedralDiagram').innerHTML=`<svg viewBox="0 0 440 320" role="img" aria-label="Sección perpendicular: diedro ${degrees} grados, ángulo entre normales ${180-degrees} grados"><path d="M${cx},${cy} L${cx+48},${cy} A48,48 0 0 0 ${arcpoint} Z" fill="#675ae8" fill-opacity=".25"/><path d="M${cx},${cy} L${ns} A58,58 0 0 0 ${ne} Z" fill="#ef8a32" fill-opacity=".3"/><path d="M${cx+100},${cy} H${cx} L${p}" fill="none" stroke="#675ae8" stroke-width="5"/><path d="M${n1} L${cx},${cy} L${n2}" fill="none" stroke="#e07a18" stroke-width="4" stroke-dasharray="9 4"/><circle cx="${cx}" cy="${cy}" r="5" fill="#35a89d"/><text x="${cx+110}" y="${cy+5}">cara 1</text><text x="${p[0]}" y="${p[1]-14}" text-anchor="middle">cara 2</text><text x="${n1[0]+12}" y="${n1[1]}">n₁</text><text x="${n2[0]}" y="${n2[1]-14}">n₂</text><text x="16" y="26">δ = ${format(degrees)}°</text><text x="16" y="302">β = ${format(180-degrees)}°</text></svg>`;
  $('dihedralCalculation').innerHTML=formula(`\\beta=180^\\circ-${degrees}^\\circ=${180-degrees}^\\circ`);
 }
 $('polarDihedral').addEventListener('input',draw);draw();
}
